    const cut = `RENTAL_ANALYSIS_OUTPUT: {"rationale": ${JSON.stringify(GOOD)}, "comp_narratives": {"0": "Clean one.", "1": "Higher than COMP 63.", "2": "Clean two.", "3": "was cut o`;
