    assert.equal(m.headlineRange({ est: 4350, low: 4000, high: 4700, n: 5 }).centre, 4300, 'exactly tied: the lower');
    assert.equal(m.headlineRange({ est: 4349.99, low: 4000, high: 4700, n: 5 }).centre, 4300);
