    assert.equal(m.GROUPINGS.region({ city: 'Calabasas' }), 'LA-border cities');
    assert.equal(m.GROUPINGS.region({ city: 'Camarillo' }), 'Ventura-area excluding LA-border');
    assert.equal(m.GROUPINGS.region({ city: null }), null);
