    const tiny = fakeResults(); tiny.mls = { mls: { baseline: [...Array.from({ length: 30 }, (_, i) => fakeRow(i, 'Camarillo')), ...Array.from({ length: 8 }, (_, i) => fakeRow(300 + i, 'Calabasas'))], size25_item2: [] } };
