    groups: { size25_item2: { county: { confidence: { High: { ranged: blockC(150, 110, 60) }, Medium: { ranged: blockC(260, 150, 70) }, Low: { ranged: blockC(40, 15, 6) } } } } },
    counties: { unknown: { overLimit: false, sharePct: 0 } },
