    const base = { ...input4, subject: { address: '2292 Buffalo Avenue', bedrooms: 3, bathrooms: 2, sqft: 1500, propertyType: 'single_family', leaseTermMonths: 12, furnished: false }, confidence: null, sourcesUsed: ['CRMLS', 'RentCast'] };
